"""Vendor maintenance log parser - fixed version."""

import csv
import sys


def summarize(path: str) -> dict[str, int]:
    counts = {"ok": 0, "malformed": 0, "high": 0}
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            temp_str = row["temperature_c"]
            # Fix Bug 1: Handle missing or invalid temperature values
            if temp_str == "" or temp_str is None:
                counts["malformed"] += 1
                continue
            try:
                temperature = float(temp_str)
            except ValueError:
                counts["malformed"] += 1
                continue
            # Fix Bug 2: 350.0 is the inclusive upper limit (acceptable)
            if temperature > 350.0:
                counts["high"] += 1
            else:
                counts["ok"] += 1
    return counts


if __name__ == "__main__":
    print(summarize(sys.argv[1]))
